#include <stdio.h>

int main() {
    int n;
    char s[505];

    scanf("%d", &n);
    scanf("%s", s);

    int maxLen = 1;

    for (int center = 0; center < n; center++) {
        int l = center, r = center;
        while (l >= 0 && r < n && s[l] == s[r]) {
            int len = r - l + 1;
            if (len > maxLen) maxLen = len;
            l--;
            r++;
        }

        l = center;
        r = center + 1;
        while (l >= 0 && r < n && s[l] == s[r]) {
            int len = r - l + 1;
            if (len > maxLen) maxLen = len;
            l--;
            r++;
        }
    }

    printf("%d\n", maxLen);
    return 0;
}
